import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tile sizes
constexpr int TILE_H  = 8;
constexpr int TILE_W  = 8;
constexpr int OC_TILE = 8;
constexpr int THREAD_TILE_W = 2;
constexpr int OC_SPLIT = 4; // splits OC_TILE accumulation across threadIdx.z to boost warps/block
constexpr int OC_PER_THREAD = OC_TILE / OC_SPLIT;
template <typename T, typename SWTensor, typename MWTensor>
__device__ __forceinline__ void load_weight_tile(
    SWTensor sW, MWTensor mW, int oc_group, int OC, int Cin, int K,
    int tid, int nthreads) {
  const int oc_base = oc_group * OC_TILE;
  const int total_w = OC_TILE * Cin * K * K;
  for (int idx = tid; idx < total_w; idx += nthreads) {
    int kw = idx % K;
    int rem1 = idx / K;
    int kh = rem1 % K;
    int rem2 = rem1 / K;
    int ci = rem2 % Cin;
    int oc_local = rem2 / Cin;
    int oc = oc_base + oc_local;
    T wval = T(0);
    if (oc < OC) {
      wval = mW(oc, ci, kh, kw);
    }
    sW(oc_local, ci, kh, kw) = wval;
  }
}
template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int OC, int K, int stride, int padding,
    int Hout, int Wout)
{
  const int BW = TILE_W / THREAD_TILE_W; // threads in x
  const int tw = threadIdx.x; // 0..BW-1
  const int th = threadIdx.y; // 0..TILE_H-1
  const int tz = threadIdx.z; // 0..OC_SPLIT-1, splits OC_TILE across threads for occupancy
  const int oc_local_offset = tz * OC_PER_THREAD;
  const int ow_base = blockIdx.x * TILE_W;
  const int oh_base = blockIdx.y * TILE_H;
  const int oc_groups = OC / OC_TILE;
  const int n = blockIdx.z; // one CTA per batch element; oc groups looped internally
  const int ow0 = ow_base + tw * THREAD_TILE_W;
  const int oh = oh_base + th;
  // Global tensors for this batch element
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * sXc),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * OC * sYc),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Full weight tensor: (OC, Cin, K, K)
  const int64_t sWoc = (int64_t)Cin * K * K;
  const int64_t sWci = (int64_t)K * K;
  const int64_t sWk  = (int64_t)K;
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, Cin, K, K),
      make_stride(sWoc, sWci, sWk, Int<1>{})
  );
  // Shared memory layout: input tile cache (loaded ONCE per CTA, reused
  // across all oc groups) plus a SINGLE weight-tile buffer. A single
  // buffer (instead of double buffering) roughly halves the per-CTA
  // shared memory footprint, which is the limiting resource for this
  // kernel's occupancy, allowing more CTAs to be scheduled concurrently
  // per SM.
  extern __shared__ unsigned char smem_raw[];
  const int IH_TILE = (TILE_H - 1) * stride + K;
  const int IW_TILE = (TILE_W - 1) * stride + K;
  T* sX_ptr = reinterpret_cast<T*>(smem_raw);
  int64_t sx_ci = (int64_t)IH_TILE * IW_TILE;
  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Cin, IH_TILE, IW_TILE),
      make_stride(sx_ci, (int64_t)IW_TILE, Int<1>{})
  );
  int64_t s_ci = (int64_t)K * K;
  int64_t s_oc = (int64_t)Cin * s_ci;
  T* sW_ptr0 = reinterpret_cast<T*>(smem_raw + (size_t)Cin * IH_TILE * IW_TILE * sizeof(T));
  auto sW0 = make_tensor(
      make_smem_ptr(sW_ptr0),
      make_shape(Int<OC_TILE>{}, Cin, K, K),
      make_stride(s_oc, s_ci, (int64_t)K, Int<1>{})
  );
  const int tid = (tz * TILE_H + th) * BW + tw;
  const int nthreads = BW * TILE_H * OC_SPLIT;
  // Input tile covering the receptive field of this CTA's output tile.
  // Loaded exactly once per CTA and reused by ALL output-channel groups,
  // eliminating redundant global memory traffic that previously occurred
  // because each oc group had its own CTA reloading the same input tile.
  const int ih_origin = oh_base * stride - padding;
  const int iw_origin = ow_base * stride - padding;
  const int total_x = Cin * IH_TILE * IW_TILE;
  for (int idx = tid; idx < total_x; idx += nthreads) {
    int iw_local = idx % IW_TILE;
    int rem1 = idx / IW_TILE;
    int ih_local = rem1 % IH_TILE;
    int ci = rem1 / IH_TILE;
    int ih = ih_origin + ih_local;
    int iw = iw_origin + iw_local;
    T xval = T(0);
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      xval = mX(ci, ih, iw);
    }
    sX(ci, ih_local, iw_local) = xval;
  }
  __syncthreads();
  int ow[THREAD_TILE_W];
  int local_iw0[THREAD_TILE_W];
  #pragma unroll
  for (int j = 0; j < THREAD_TILE_W; ++j) {
    ow[j] = ow0 + j;
    local_iw0[j] = (tw * THREAD_TILE_W + j) * stride;
  }
  const bool row_valid = (oh < Hout);
  const int local_ih0 = th * stride;
  for (int oc_group = 0; oc_group < oc_groups; ++oc_group) {
    const int oc_base = oc_group * OC_TILE;
    // Load the current oc group's weight tile into the single shared-memory
    // buffer. Using one buffer instead of double buffering trades away
    // weight-prefetch overlap for a much smaller per-CTA shared memory
    // footprint, allowing more CTAs to be resident per SM concurrently.
    load_weight_tile<T>(sW0, mW, oc_group, OC, Cin, K, tid, nthreads);
    __syncthreads();
    auto sWcur = sW0;
    float acc[THREAD_TILE_W][OC_PER_THREAD];
    #pragma unroll
    for (int j = 0; j < THREAD_TILE_W; ++j) {
      #pragma unroll
      for (int i = 0; i < OC_PER_THREAD; ++i) acc[j][i] = 0.0f;
    }
    if (row_valid) {
      for (int ci = 0; ci < Cin; ++ci) {
        for (int kh = 0; kh < K; ++kh) {
          int ih_local = local_ih0 + kh;
          for (int kw = 0; kw < K; ++kw) {
            float xval[THREAD_TILE_W];
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_W; ++j) {
              int iw_local = local_iw0[j] + kw;
              xval[j] = (float)sX(ci, ih_local, iw_local);
            }
            #pragma unroll
            for (int oc_local_idx = 0; oc_local_idx < OC_PER_THREAD; ++oc_local_idx) {
              int oc_local = oc_local_offset + oc_local_idx;
              float wval = (float)sWcur(oc_local, ci, kh, kw);
              #pragma unroll
              for (int j = 0; j < THREAD_TILE_W; ++j) {
                acc[j][oc_local_idx] += xval[j] * wval;
              }
            }
          }
        }
      }
    }
    if (row_valid) {
      #pragma unroll
      for (int j = 0; j < THREAD_TILE_W; ++j) {
        if (ow[j] >= Wout) continue;
        #pragma unroll
        for (int oc_local_idx = 0; oc_local_idx < OC_PER_THREAD; ++oc_local_idx) {
          int oc_local = oc_local_offset + oc_local_idx;
          int oc = oc_base + oc_local;
          if (oc >= OC) continue;
          float bval = 0.0f;
          if (Bias != nullptr) {
            bval = (float)Bias[oc];
          }
          mY(oc, oh, ow[j]) = static_cast<T>(acc[j][oc_local_idx] + bval);
        }
      }
    }
    // Ensure all threads are done reading sWcur (it may be overwritten two
    // iterations from now) and that the just-prefetched next tile is fully
    // visible before it is used as the current tile in the next iteration.
    __syncthreads();
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, Cin, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t OC = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square (K x K)");

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(OC % OC_TILE == 0, "out_channels must be a multiple of OC_TILE for this kernel");

  int64_t Hout = (H + 2 * padding - K) / stride + 1;
  int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  dim3 block(TILE_W / THREAD_TILE_W, TILE_H, OC_SPLIT);
  dim3 grid(
      (unsigned)((Wout + TILE_W - 1) / TILE_W),
      (unsigned)((Hout + TILE_H - 1) / TILE_H),
      (unsigned)(N)
  );

  int IH_TILE = (TILE_H - 1) * stride + (int)K;
  int IW_TILE = (TILE_W - 1) * stride + (int)K;
  size_t smem_bytes = (size_t)OC_TILE * Cin * K * K * sizeof(float)
                     + (size_t)Cin * IH_TILE * IW_TILE * sizeof(float);
  int device;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  TORCH_CHECK((size_t)max_smem_optin >= smem_bytes,
      "Required shared memory (", smem_bytes,
      " B) exceeds device max opt-in shared memory per block (",
      max_smem_optin, " B) for Cin=", Cin, ", K=", K,
      ". Reduce TILE_H/TILE_W/OC_TILE for this input size.");
  static size_t smem_attr_bytes = 0;
  if (smem_attr_bytes < smem_bytes) {
    auto attr_err = cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
        "Failed to opt-in to ", smem_bytes,
        " bytes of dynamic shared memory: ", cudaGetErrorString(attr_err));
    smem_attr_bytes = smem_bytes;
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)OC, (int)K, (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)
        self._ext = conv2d_ext

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

