  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, Cin, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t OC = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square (K x K)");

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(OC % OC_TILE == 0, "out_channels must be a multiple of OC_TILE for this kernel");

  int64_t Hout = (H + 2 * padding - K) / stride + 1;
  int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  dim3 block(TILE_W, TILE_H);
  dim3 grid(
      (unsigned)((Wout + TILE_W - 1) / TILE_W),
      (unsigned)((Hout + TILE_H - 1) / TILE_H),
      (unsigned)(N * (OC / OC_TILE))
  );

  size_t smem_bytes = (size_t)OC_TILE * Cin * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)OC, (int)K, (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
